# srt-live-transmitでプライベートマルチキャストから取得して、
# tsmに流してTS監視するスクリプト

multicastport="$1"
packetsize="$2"
recvbuf="$3"
confpath="${4:-/usr/local/etc/tsa/tsm.conf}"

# 引数の検証
if [ $# -lt 3 ]; then
  echo "Usage: $0 <MULTICASTPORT> <PACKETSIZE> <RECVBUF> [CONFPATH]"
  exit 1
fi

srt-live-transmit \
    udp://239.0.0.1:$multicastport\?adapter=127.0.0.1\&pkt_size=$packetsize\&rcvbuf=$recvbuf \
    file://con \
    -loglevel error \
    -verbose | \
tsm \
    -d 1 \
    -b 65536 \
    -c "$confpath"
analyze:
  stats: 10
  start_delay: 5000
  charset_enc: "UTF-8"
  charset_dec: "UTF-8"

alarm:
#  file: /usr/local/etc/tsa/alarm.yml
  host: 127.0.0.1

log:
  events: /tmp/tsm_events.log
  metrics: /tmp/tsm_metrics.log
  overlay: /tmp/tsm_overlay.log
"}

