//--------------------------------------------------------------------------------
int logger::stop() {
	m_enable = false;
	m_logger->flush();

	return 0;
}

//--------------------------------------------------------------------------------
int logger::event(const ordered_json &j) {
	if(!m_enable) {
		return 0;
	}

	ordered_json t = { timestamp(), { "type", "event" } };
	if(!j.empty()) {
		t.update(j);
	}

	m_logger->info(t.dump());

	return 0;
}

